def find_cycle_start(vals: list[int], pos: int) -> int:
    if not vals: return -1
    class Node:
        def __init__(self, val):
            self.val = val
            self.next = None
    nodes = [Node(v) for v in vals]
    for i in range(len(nodes) - 1):
        nodes[i].next = nodes[i+1]
    if pos != -1:
        nodes[-1].next = nodes[pos]

    head = nodes[0]
    slow, fast = head, head
    while fast and fast.next:
        slow = slow.next
        fast = fast.next.next
        if slow == fast:
            slow = head
            while slow != fast:
                slow = slow.next
                fast = fast.next
            return nodes.index(slow) if pos != -1 else -1
    return -1
